#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (6) ---
patchFile('siman_014/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The law of a fetus in an animal's womb. In it are 6 seifim. An animal straining to give birth; and the fetus brought out its head—even though it returned it—behold it is like one born (yelud) and is not permitted through its mother's shechitah. Therefore if it is eight months—alive or dead—or nine months dead, it is forbidden. And if it is nine months alive, it is permitted through its own shechitah.`,
  '2#main': `It brought out its hand and returned it (meaning: before shechitah)—what came out from the limb to the outside is forbidden. But what remained of it inside and the place of the cut is permitted. If it did not return it before shechitah—even the place of the cut is forbidden; but what is inside is permitted, even if it is its minority. {Rama: And all this applies only regarding that it be permitted through its mother's shechitah like other fetus found in her; but if the animal later gave birth to it—even the limb that came out and was returned is permitted, for its own shechitah permits everything (so Beit Yosef brought R' Yosef ibn Chaviv and Kol Bo in the name of some say, and so Maharshal proved in chapter Behemah HaMekishah seif 1, and so is the implication of the poskim—and it is straightforward).}`,
  '3#main': `If most of the fetus came out, behold it is like one born; and if half came out with majority of a limb—or if most of it came out with minority of a limb—behold it is like one born.`,
  '4#main': `It brought out one limb and returned it, and again brought out another limb and returned it, until it completed the majority of the minority that had not come out—it is permitted. And if it cut off each and every limb at the time it brought it out—even the minority that remained inside is forbidden.`,
  '5#main': `A fetus that brought out a limb and the limb became forbidden; and afterward the mother was slaughtered and the fetus was taken out and behold it is female—its milk is forbidden to drink, since it comes from all the limbs and there is one forbidden limb; and behold this is like milk of a treifah that was mixed into kosher milk.`,
  '6#main': `One who extends his hand into the animal's womb and cuts from the spleen or kidneys and the like and leaves the pieces inside its womb and afterward slaughters it—behold those pieces are forbidden because of eiver min hachai, even though they are inside its womb; but if he cut from the fetus in the womb and did not remove it and afterward slaughtered it—behold the pieces of the fetus or its limb are permitted, since it did not come out. (Rambam law 9.) {Rama: And if he slaughtered a fetus in its mother's womb, it is not called shechitah (Ran and it is an unresolved question in chapter Behemah HaMekishah and it was not resolved).}`,
});

// --- siftei-kohen (14) ---
patchFile('siman_014/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `<b>And the fetus brought out its head.</b> In Choshen Mishpat siman 277 it is explained that most of the forehead is as if its entire head came out; and even though in the Talmud at the beginning of chapter Yesh Bechor and in Rambam chapter 2 of Laws of Inheritance and in Shulchan Aruch there it says that if the forehead came out it is as if all of it came out—it is plain that this refers only to the law of forehead, which is like its head; but certainly most of the forehead is like all of it and is counted as if its entire head came out; and so the Pri Megadim and Semag there s.k. 6 and Perishah here; and so below siman 194 in Tur and Rambam and Bach in Choshen Mishpat deleted the word "most"—and for practical law, as I wrote.`,
  '1#ב': `<b>All forbidden.</b> But when it is nine months alive, all of it is permitted through its own shechitah specifically—even if its mother is treifah it is permitted thereby, for it is like one born (yelud).`,
  '2#א': `<b>What came out from the limb to the outside is forbidden.</b> For it is said "and flesh in the field, treifah, you shall not eat," and Chazal expounded: once flesh went outside its partition—that is, the womb which is the partition of the fetus—it is forbidden.`,
  '2#ב': `<b>Even if it is its minority.</b> Of the limb.`,
  '2#ג': `<b>And all this, etc., only regarding that it be permitted, etc.</b> Meaning: its mother's shechitah is what diminishes its power; for if it was not born before its mother's shechitah—even though it is nine months alive—the limb is forbidden and its own shechitah afterward does not help it; and see the reason in s.k. 11.`,
  '2#ד': `<b>But if the animal later gave birth to it.</b> Specifically before shechitah; but after shechitah—even if born through the birth canal—it is forbidden, as is proved in Tur and Beit Yosef; and so the Bach; and with this what was left in Darkei Moshe and Perishah in Beit Yosef's words requires study—see there.`,
  '3#א': `<b>And if half came out with majority of a limb.</b> For example, most of its hand came out; and when one estimates what came out from the fetus, it is only half; and if one adds the minority of the hand that remained inside after the majority of the hand that came out, it becomes majority—we rule on the minority of the hand inside after the majority of the hand that came out to complete the majority of the fetus, and it is forbidden—end of Tur; and this law is an unresolved question in the Talmud and was not resolved, and the poskim ruled stringently; therefore the Tur wrote in siman 319 regarding firstborn that the one born after it is a doubtful firstborn; and therefore this is clear that its own shechitah does not help it either, lest it not be considered yelud; but what remained inside is permitted through its own shechitah in any case—if yelud, plainly it is permitted; and if not yelud, it is permitted through its mother's shechitah, for it did not come out at all. And if it is nine months dead or eight months alive—we are concerned lest it be yelud and all is forbidden, even what is inside; and if nine months alive, what came outside is forbidden lest it not be yelud and it is flesh that went outside its partition and was forbidden and its own shechitah does not help it either since it was not born before its mother's shechitah; but what remained inside is permitted in any case—even if its mother was treifah, through its own shechitah, as explained in siman 13; and even if it did not return what it brought out, what remained inside is permitted in any case. And what the Tur wrote in seif 4 "and if it cut each limb when it brought it out, even the minority inside is forbidden"—there, since it cut most of its limbs, it cannot be permitted through its own shechitah; or it deals with eight months or nine months dead—and see Perishah who wrote similarly.`,
  '3#ב': `<b>Or if most of it came out with minority of a limb, etc.</b> It is plain in the Talmud that it is yelud; and the Mechaber who wrote "in one case it is yelud" does not mean to equate them entirely, and he relied on what he wrote below siman 319: if most came out with minority of limb it is certainly yelud; and with half with majority of limb it is doubtful—and it is astonishing on the Pri Megadim who wrote at the beginning and end that the reason is because we go stringently—whereas certainly this is not so except when most came out with minority of limb, which is plainly yelud; and therefore when it is nine months alive all is permitted through its own shechitah specifically; and when nine months dead or eight months alive—all is forbidden, even what is inside—and see in the s.k. before this.`,
  '3#ג': `<b>Most with minority of limb.</b> Thus the Tur: we do not say to add minority of limb that came out after majority of limb inside; rather we add it after majority of fetus that came out, and it is forbidden—end of his words; and so Rashi; and it appears his words are not precise when he says "after majority of fetus," for without this minority of limb outside there is no majority of fetus; and it seems he calls it "majority of fetus" by its end; and the same if inside was more than outside without the minority of limb—we rule on the fetus outside, since with the minority of limb with it there is majority of fetus outside; and so it appears from the Tur below siman 319—and examine.`,
  '4#_': `<b>Even the minority that remained inside is forbidden.</b> This too is an unresolved question in the Talmud whether we require the majority at once or not; and we rule stringently—and see s.k. 7.`,
  '5#א': `<b>Its milk is forbidden to drink.</b> This too is an unresolved question in the Talmud (daf 69a): what is the law of sucking its milk—is milk in general not like eiver min hachai (as in siman 81 s.k. 12 and siman 87 s.k. 9) and this too is permitted, or perhaps there it has a remedy for its prohibition through shechitah—teiku; and so Rambam: behold this is forbidden to drink from doubt. The Bach challenged: why did the Talmud not ask similarly regarding ben pakuah that came on a regular animal and engendered, that the offspring has no remedy because of shehiyah, as above siman 13 s.k. 12; and he answered: there it is plain it is permitted, for it is not treifah but only that shechitah does not permit it, and it is like what the Rashba wrote; and the Rabeinu Yerucham (siman 24 s.t. 15) regarding a dislocated animal wrote: its milk is permitted because a dislocated animal is not treifah but only shechitah is not effective in it; but here it is forbidden because of treifah, and milk of treifah is forbidden—end of his words. But this explanation of the sugya does not seem right to me; and further, the dislocated animal there is according to Maharshal that a dislocated animal is not treifah while alive, unlike above where the offspring is treifah because one of its simanim is as slaughtered—consider for yourself: if he slaughtered one siman and afterward left it, is its milk permitted, lest one say he will finish the shechitah afterward—and this case is similar; and further, with dislocated animal it had a time of fitness, unlike here where from the day it was born it has no remedy. And this distinction is explained in Perishah. And that the Talmud asks thus specifically regarding issur yotzei—for the prohibition is because of eiver min hachai, and milk in general is also like eiver min hachai—and so the Rashba in his chiddushim: thus the question arises—this limb has no prohibition in itself like treifah at all, but because it has no simanim to permit it through shechitah, and behold the whole body is like flesh placed in a basket, and the limb that came out alone remained alive—what difference is there between this milk and other milk from a live animal; or perhaps it is diminished—for there its life stands to be corrected through shechitah, but this fetus's life has no eternal remedy through shechitah—end of his words; and so the Ran; but above, where the whole animal is forbidden because one siman is as slaughtered, plainly it is forbidden.`,
  '5#ב': `<b>And behold this is like milk of treifah that was mixed, etc.</b> The Bach wrote: if there were sixty in the animal in flesh, gidim, and bones against the forbidden limb, all the milk is permitted because of mixtures that are nullified in sixty—end of his words; and so the Pri Megadim; and I am astonished—who told them this prophecy, that perhaps from a small limb the milk grows much more than from another large limb, and it is never nullified; and so appears the plain meaning of the Talmud and later poskim. I found that Perishah wrote this reasoning; however one may say it should only be a doubt whether there are sixty, since it is min b'mino that is nullified from the Torah by majority, but rabbinically requires sixty—it is a rabbinic doubt, and we rule leniently, as below siman 98 seif 2; and so we say below siman 81 s.k. 8—see there.`,
  '6#א': `<b>And he cut from the spleen and kidneys.</b> He mentioned these because the animal is not rendered treifah by cutting them, as below siman 43 and 44; and in the Talmud (daf 69a) it challenges from fetus and answers that it is written "it"—whole—and not "it" lacking, unlike the Pri Megadim who omitted this sugya and wrote another reason—see there.`,
  '6#ב': `<b>And if he slaughtered a fetus, etc.</b> This is an unresolved question in chapter HaMekishah (daf 74) and it is proved there that it deals with one that came out after its slaughter from the womb before its mother's shechitah—for then even if nine months alive its slaughter is neveilah from doubt, lest shechitah applies only after it goes out into the air of the world; but where it did not come out before its mother's shechitah, it is permitted through its mother's shechitah. And the Rabeinu Yerucham summarized understandably and relied on above (and therefore since it is doubtful it is not called shechitah, it is forbidden to slaughter the mother after it on the same day, lest it be shechitah). And the Pri Megadim did not know the source of this law and therefore wrote the reason that it is not shechitah because of chaladah—and the sugya there does not go that way at all according to this—see there; rather the reason is plain as I wrote, and so Rashi there; and the Lechem Chamudot already challenged on this daf 184 end of seif 1.`,
});

// --- turei-zahav (10) ---
patchFile('siman_014/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Its head.</b> Meaning: most of its forehead, as written in Choshen Mishpat siman 277.`,
  '2#א': `<b>From the limb to the outside is forbidden.</b> For it is written "and flesh in the field, treifah, you shall not eat"—once it went outside its partition it is forbidden; and this fetus's partition is the womb to permit it through its mother's shechitah; and since it went outside its partition—that is, into the air of the world—it is forbidden from the permission of its mother's shechitah.`,
  '2#ב': `<b>And the place of the cut.</b> For this is the distinction between inner and outer; and since it returned it, one need not cut toward the inside but only narrows and cuts, and the place of the cut is permitted—for we apply to it "in behemah you may eat"; but if it did not return, we do not apply "in behemah" at the place of the cut.`,
  '2#ג': `<b>Even if it is its minority.</b> For we hold: birth does not apply to limbs like R' Yochanan, and not like Rav who holds birth applies to limbs.`,
  '3#_': `<b>Half with majority of limb.</b> For example, most of its hand came out; and when what came out from the fetus remains only half; and if one adds the minority of the hand inside after the majority of the hand that came out to complete majority of the fetus—it is forbidden; and this is an unresolved question in the Gemara and was not resolved, and we hold stringently; and therefore it is clear that its own shechitah does not help either, lest it not be considered yelud; but what remained inside is permitted through its own shechitah in any case—if yelud, plainly permitted; if not yelud, permitted through mother's shechitah, for it did not come out at all. But the second case—most came out with minority of limb—is plain in the Gemara that we follow majority of the fetus and not majority of limb inside; and if so, even leniently we hold yelud; and if so, its own shechitah helps even for what came out; and therefore he should not have written the same language for both "behold it is yelud"; also the Tur's language "and so, etc." is not precise, for they are not in one category.`,
  '5#א': `<b>From all the limbs, etc.</b> This is an unresolved question in the Gemara: shall we say that since all milk in general is like eiver min hachai and nevertheless permitted, here too no difference; or perhaps there it has a remedy for its prohibition through shechitah, here it has no remedy through shechitah (and see what I wrote in siman 24 seif 15)—and it was not resolved, and we rule stringently. And it appears clear to me regarding ben pakuah that came on a regular animal, that the offspring has no remedy, as in siman 13 seif 4, that milk of that offspring is also forbidden to drink—for behold all of it is prohibition, since half is slaughtered and it is like anything slaughtered half literally. And that it did not ask regarding offspring of ben pakuah that came on the animal—that law that the offspring has no remedy is from Rav Mesharshia according to the view that we are concerned for the father's seed, and it is a dispute among amoraim in chapter Oto V'et Beno—therefore it is fine to ask regarding issur yotzei, which is according to all; but for practical law certainly one reason applies—that there is no remedy for that offspring's prohibition through shechitah; this seems plain to me, except I saw in my humble opinion he wrote from this challenge that it did not ask regarding ben pakuah we mentioned—that there in truth the milk is permitted, for although the offspring has no remedy through shechitah because of shehiyah, it is only that shechitah does not permit it, but while alive there is no prohibition, for it has no trace of treifah—and he compared it to uprooted tree that Beit Yosef brought below where there is no prohibition but only shechitah is not effective—end of his words. And for practical law this is difficult: for Rashi explicitly in chapter Behemah HaMekishah (Chullin daf 69) regarding ben pakuah that engendered—forbidden is all offspring—behold he calls it forbidden, and how is its milk permitted, for it comes from prohibition; and further proof: we say there in the Gemara what is the law regarding its seed—that issur yotzei—how is it: if it goes to a superior animal, why particularly this that has issur yotzei—even regular ben pakuah too, for Rav Mesharshia said according to those who are concerned for father's seed, ben pakuah that came on a superior animal—that offspring has no remedy, etc.; and if you say this "has no remedy" has no prohibition—how compare it to issur yotzei regarding offspring that comes from it? They are not similar—for in issur yotzei there is prohibition, in ben pakuah there is no prohibition, only no permission of shechitah; rather one must equate them literally, that as in issur yotzei truly forbidden, so in ben pakuah; and as at first he compared them to forbid the offspring, so in conclusion the offspring is permitted only regarding milk one must equate, and what prohibition is in this is in that—as I wrote, clearly the offspring that has no remedy is fully forbidden and its milk forbidden. And what does it challenge "why particularly, etc."—from that of Rav Mesharshia? We said above that it is fine to formulate according to all; one may say: since it is relevant to ask according to all like Rav Mesharshia, therefore it is preferable to ask according to all, unlike here where there is clear prohibition like Rav Mesharshia—one cannot say such a question, since we find clear prohibition in this.`,
  '5#ב': `<b>And behold this is like milk of treifah that was mixed, etc.</b> This language is superfluous and indicates apparently that nullification in sixty applies here; and so my humble opinion: if there were sixty in the animal in flesh, bones, and gidim against the forbidden limb, all milk is permitted because of mixtures nullified in sixty. And in my humble opinion one should not be lenient—for it is known that limbs are not equal regarding blood in them, for there is a limb with mostly flesh and minority bone—then there is more blood, and vice versa; and so regarding milk coming from blood in limbs—and one cannot estimate this in sixty; and so I saw in Perishah; and further proof from siman 86 seif 5 that we require sixty-one eggs because not all eggs are equal—and this matter is similar, since one cannot ascertain the calculation; and as written siman 81 seif 2 that there is a distinction in this. The superfluous language here in Shulchan Aruch according to Rambam indicates another matter: for in the Gemara at first it was an unresolved question regarding seed born from that issur yotzei whether forbidden because it comes from prohibition or not, and we conclude that from force we do not say and it is permitted; only it is a question regarding milk to drink it—therefore we hear from Rambam he did not err to say the milk comes from force of limbs, for so the language implies at first "since it comes from all the limbs"—if so it would be like from force of limbs, which is not so, for all force is permitted; rather the milk comes literally in substance from the limbs as if nursing milk before us; and that he wrote "and this is like milk of treifah mixed, etc." means milk literally mixed, not only force like matter of offspring born—as above, correct.`,
  '6#א': `<b>From the spleen.</b> He mentioned things by which the animal is not rendered treifah; and it is forbidden to eat, for it is written "it you shall eat," and we expound "it" when whole and not when lacking.`,
  '6#ב': `<b>From the fetus, etc.</b> Meaning: even milk is permitted, for it is written "in behemah you may eat."`,
  '6#ג': `<b>It is not called shechitah.</b> In the Gemara it is an unresolved question whether shechitah helps while it has not gone out into the air of the world—and it was not resolved, and we go stringently. In Levush he did not see the source of this law and understood the reason is chaladah—and it is an error; and see what I wrote in siman 24 seif 8.`,
});

// --- baer-heitev (12) ---
patchFile('siman_014/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `<b>Like one born (yelud).</b> And the Taz wrote: the same if it brought out most of its forehead, as in Choshen Mishpat siman 277.`,
  '1#ב': `<b>Itself.</b> And the Shach wrote: even if its mother is treifah, for it is yelud to it.`,
  '2#א': `<b>Forbidden.</b> Because it is said "and flesh in the field, treifah, you shall not eat," and our Sages expounded: once flesh went outside its partition—that is, the womb which is the partition of the fetus—it is forbidden.`,
  '2#ב': `<b>The cut.</b> Meaning: the distinction between outer and inner. Beit Yosef wrote: and we practice that we cut until the place where the bone ends. And so with a broken bone where there is no treifah in the body of the behemah or fowl—in any case that limb is forbidden—we cut the entire limb.`,
  '2#ג': `<b>Everything.</b> And the Shach explained: specifically if it gave birth before shechitah; but after shechitah—even if born through the birth canal—it is forbidden; and with this what was left in Darkei Moshe and Perishah in Beit Yosef's words is resolved. Beit Yosef wrote: specifically that it returned the limb before its mother's shechitah; but otherwise, even though it gave birth afterward—that limb with the place of cut is forbidden as law of dangling limb (eiver meduldal), since this limb remained dangling when it came out from its mother's womb—it still stands in prohibition of dangling limb and is not permitted through its own shechitah. And Peri Chadash disagrees.`,
  '3#א': `<b>Limb.</b> And the Shach explained: for example, most of its hand came out; and when one estimates what came out from the fetus, it is only half; and if one adds minority of hand inside after majority of hand that came out, it becomes majority—we rule on minority of hand inside after majority of hand that came out to complete majority of fetus, and forbidden; and this law is unresolved in the Talmud and poskim ruled stringently; therefore the Tur wrote in siman 319 regarding firstborn that the one after is doubtful firstborn; and therefore this is clear that its own shechitah does not help, lest it not be yelud; but what remained inside is permitted through its own shechitah in any case—if yelud, plainly permitted; if not yelud, permitted through mother's shechitah, for it did not come out at all.`,
  '3#ב': `<b>Yelud.</b> And the Shach wrote: this is plain in the Talmud that it is yelud; and the Mechaber who wrote everything in one case does not mean to equate them fully, but when most came out with minority of limb it is certainly yelud; and with half with majority of limb it is doubtful; and the same if inside was more than outside without minority of limb—we rule on fetus outside.`,
  '4#_': `<b>Forbidden.</b> And the Shach wrote: this too is unresolved in the Gemara and was not resolved, and stringently.`,
  '5#א': `<b>Forbidden.</b> And the Shach wrote: the same with ben pakuah that came on a regular animal—the offspring has no remedy, as in siman 13 seif 4, that milk of that offspring is also forbidden to drink—and not like the Bach.`,
  '5#ב': `<b>Kosher.</b> And behold the Bach and Shach permit if there appear to be sixty in the animal against that limb—it is a rabbinic doubt of min b'mino that from the Torah is nullified in majority, but rabbinically requires sixty; however the Taz ruled one should not be lenient (and Nekudot HaKesef disagrees), lest perhaps from this small limb more milk grows than from a large limb; and the Shach concludes it is a rabbinic doubt and we rule leniently; and so Peri Chadash.`,
  '6#א': `<b>In them.</b> And the Shach wrote: he mentioned these because the animal is not rendered treifah by them; and in the Talmud it challenges why different from fetus that is permitted to eat, etc., and answers that it is written "it" whole and not lacking.`,
  '6#ב': `<b>Shechitah.</b> And the Shach wrote: this is unresolved in the Talmud and deals with one that came out after its slaughter from the womb before mother's shechitah—for then even if nine months alive its slaughter is neveilah from doubt, lest shechitah is only after going out into the air of the world; but where it did not come out before mother's shechitah, it is permitted through mother's shechitah; and therefore since doubtful it is not called shechitah, forbidden to slaughter the mother after it on the same day, lest it be shechitah. However it requires study—for in any case it is chaladah—and examine.`,
});

// --- beer-hagolah (11) ---
patchFile('siman_014/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Mishnah Chullin daf 64.`,
  '2#א': `Statement of Rav there in the name of "flesh in the field, treifah" that went outside its partition.`,
  '2#ב': `Conclusion of the Gemara there.`,
  '2#ג': `There, according to the version of the mishnah in the West and like R' Yochanan that the Rif did not establish.`,
  '3#א': `There in the Gemara.`,
  '3#ב': `There it is an unresolved question and was not resolved, and the poskim ruled stringently.`,
  '4#א': `There, first unresolved question, and it came to be taught and was not resolved, and leniently.`,
  '4#ב': `There, final unresolved question, and stringently—the Rashba and Rosh.`,
  '5#א': `Beit Yosef—and to exclude if birth preceded its mother's shechitah, that its own shechitah helps to permit that limb; and so one may explain Rambam's words in chapter 5 of Laws of Forbidden Foods law 12, and as the Rama wrote above seif 2.`,
  '5#ב': `Unresolved question there if it returned it and afterward was born; and Rashi explained: the same if its mother was slaughtered and they removed it—and it was not resolved, and poskim ruled stringently.`,
  '6#_': `Mishnah there.`,
});

// --- beur-hagra (6) ---
patchFile('siman_014/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#_': `<b>(Seif 2) It brought out its hand, etc.</b> Like Rav and Shmuel that R' Yehudah was established; and all the more so the later version that R' Yehudah too concedes; and as the Rif and Rosh explained.`,
  '2#_': `<b>But what (is inside), etc.</b> Gemara there "if regarding fetus, etc."; and so there in the sugya several times.`,
  '3#_': `<b>Even, etc.</b> Avodat HaGershuni; and as the Rif and Rosh explained.`,
  '4#_': `<b>And all this not, etc.</b> From that it says there (69a) what is the law regarding its seed, etc.—even regular ben pakuah too, etc.—it implies that in ben pakuah we deal with it; otherwise what does it challenge—we were taught regarding complete offspring; and it says there "not correct" that ben pakuah goes like it; and Rashi there s.v. ben pakuah, etc.`,
  '5#_': `<b>(Seif 3) Or if most of it came out, etc.</b> Plain in the Gemara there.`,
  '6#_': `<b>(Seif 6) And if he slaughtered a fetus, etc.</b> There 74a.`,
});

// --- kereti (17) ---
patchFile('siman_014/kereti/part-001.txt', 'kereti', {
  '1#א': `The animal straining to give birth—in plain language one may say he mentioned "straining" even though it returned its head, and one might say that because of the strain the head came out, but the time of birth had not yet arrived—he teaches us nevertheless that since it brought out the head, it is birth.`,
  '1#ב': `Its head—meaning: most of its forehead; so the later authorities wrote.`,
  '1#ג': `Permitted through its own shechitah—even if the mother is treifah.`,
  '2#א': `<b>Even if it is its minority</b>—meaning: minority of a limb in the animal; and one might say this too is yelud—he teaches us we do not hold birth applies to limbs.`,
  '2#ב': `That its own shechitah permits; and even though they said "flesh in the field"—once it goes outside its partition it has no remedy—here it has remedy through slaughter of the offspring; there is no difficulty, for since the offspring was slaughtered the matter is revealed retroactively that it never went outside its partition—and it is straightforward.`,
  '2#ג': `Permits everything; but if the mother was slaughtered and afterward the offspring came out—even through birth—in any case it was already slaughtered and one cannot permit the limb that came out.`,
  '2#ד': `Everything; and if it brought out a limb and afterward the mother was slaughtered and she was treifah such that the offspring has shechitah—the limb too is dead as if born before mother's shechitah—Peri Chadash, not like the Bach; and see Peleti that I made adjacent to it.`,
  '3#א': `Half with majority of limb—came out half and half; and his daughter: the half that came out is majority of the hand; and if so, if we throw the minority that is inside after majority of hand outside, here is departure of majority—it is unresolved and we go stringently that mother's shechitah does not permit; and likewise in reverse, if afterward the mother was slaughtered, we say perhaps it is not yelud and therefore offspring's shechitah does not help further, for mother's shechitah already permitted it; and what is outside—all treifah.`,
  '3#ב': `Most with minority of limb—I wrote in Peleti by way of parable: outside six olives and minority of hand goes up three quarter-olives; and inside with majority of hand five and a half olives; and if we say we throw minority of hand inside—for majority of hand outside, behold inside is majority six and a quarter; but now that aside from the hand there is majority outside, we do not rule on minority of hand inside—and behold outside is majority; and it is plain; and this is the unresolved question that was resolved; and we judge in it both to be lenient and to be stringent.`,
  '5#א': `Its milk is forbidden; and the same for what we hold—ben pakuah that came on a regular animal and engendered—that offspring has no remedy; milk of that offspring is forbidden, as milk of treifah—not like the Bach who compared it to uprooted tree that milk is permitted—the Taz and Shach.`,
  '5#ב': `Like milk of treifah that was mixed—the Bach's view: if according to visual estimate in the animal there is sixty against the outgoing limb, permitted—for presumably in the milk too there is sixty and it is nullified. Perishah and Taz forbid—for not all limbs are equal in affecting milk, one increases and one decreases. Shach and so Peri Chadash wrote: since in majority certainly they are nullified, only doubt whether there are sixty—like case of nispach below siman 98; and see Peleti what I wrote, that otherwise there is double doubt, as Maharshal wrote.`,
  '5#ג': `Treifah, etc.—lest you say it is only force and it is zeh v'zeh gorem and permitted—he teaches us it is not so, but it is like prohibition mixed in permission; and see Peleti.`,
  '5#ד': `In kosher milk—see Peleti that I raised: if the outgoing limb is such that one can cut it from the animal and it will not be rendered treifah thereby, then its milk is forbidden—for this is nullifying prohibition l'chatchila; but if impossible, the milk is permitted if one may say there is doubt here, as the Shach wrote.`,
  '6#א': `From the spleen—see what I wrote above in siman 43 at length.`,
  '6#ב': `Even though it is inside its womb—for it is written "it" whole and not lacking—Taz and Shach; and I did not know this is the Gemara's reasoning, but in conclusion the Gemara retracted and holds what is permitted in the offspring is because it is written "behemah" in behemah, and in that term no reason is needed why not from its body parts permitted; and on the challenge "if so they should change the term," the Gemara changed to another term since it is not relevant to the law—I shortened.`,
  '6#ג': `It is not called shechitah—it is unresolved in the Gemara, so the later authorities; and they challenged the Pri Megadim who gave the reason of chaladah. And see Peleti where I debated this—that Tosafot's view is prohibition is only because of slaughtering at night, and b'dieved permitted—requires study.`,
  '6#ד': `Shechitah—and this is when they removed it before mother's shechitah; but after mother's shechitah permits everything.`,
});

// --- peleti (6) ---
patchFile('siman_014/peleti/part-001.txt', 'peleti', {
  '1#_': `The animal straining to give birth—the Gemara mentioned "straining" to teach that it deals with a dead fetus, and teaches us that the head is like birth even in miscarriages; therefore it teaches "straining"—not that on its own it brought out the offspring/limb, for it is dead, only strain and pains brought it out in the order of strain without assistance from the animal. And from this is understood what Maharsha wrote there in Tosafot: why does the Gemara challenge—what does it teach us, perhaps it teaches us that even in miscarriages the head exempts; and answer: there is no resolution in the mishnah, lest it deal with its head alive and viable offspring. And this is not so—for from the mishnah it teaches thus, otherwise the Gemara's answer is difficult, why do we not learn behemah from adam regarding head exempts, etc. From this it is clear in explanation that the head is yelud; and it must be that here it teaches even for miscarriages the head exempts; and the mishnah here in any case deals with miscarriages for the reason I wrote, or possibly the mishnah is unstam R' Meir, and for R' Meir viable offspring—shechitah does not permit at all. In any case it is proved not like Maharsha that the mishnah here certainly deals with miscarriage.`,
  '2#_': `But if it gave birth, etc.; and if the mother was slaughtered and found treifah, until the offspring found inside requires shechitah—for the Merciful One koshered four simanim—if offspring's shechitah is effective also for the outgoing limb: Bach's view it is not effective, and so Shach and Peri Chadash challenged that it is effective. And his words seem without proof, for he brought proof from that which we say to R' Meir there is no issur yotzei—learn from this offspring's shechitah helps for limb too—there is no proof, for plainly for R' Meir mother's shechitah does not work at all on offspring, plainly offspring's shechitah permits the limb; but with treifah where her shechitah helps even for outgoing limb to purify from neveilah status, as appears from mishnah there daf 68b—if so, mother's shechitah already took effect and offspring's shechitah no longer helps for eating permission. However there is proof from that which R' Yirmiyah asked what to be concerned for its seed, and the Gemara challenged: it implies it came on superior animal—why particularly this with issur yotzei—even superior ben pakuah, for Rav Mesharshia said according to those concerned for father's seed, ben pakuah on superior animal—that offspring has no remedy, etc.; and it is difficult what is the challenge—perhaps the question is in such a case that it brought out its hand and afterward mother was slaughtered and she is treifah—then offspring has shechitah but outgoing limb has no shechitah, and it came on regular animal—offspring has remedy for it has shechitah from every side, but limb forbidden for we are concerned for its seed. Fine, from that we say to R' Yehudah there is issur yotzei, there is prohibition of milk and blood—no difficulty, perhaps in such a case—and if so offspring needs and shechitah is effective and there is prohibition of milk and blood in it. Unlike regarding limb there is issur yotzei that is not permitted through shechitah. No difficulty—for it deals with one that came on daughter pakuah like it, and therefore not needed as above; rather this challenge from the outset does not exist, for daughter pakuah like it is not needed, only it deals in such a case. And truly according to Rashi and his supporters who hold that of Rav Mesharshia does not exist according to those who hold the Merciful One koshered four simanim—if so the Gemara that challenges R' Meir is not needed as above, since we do not hold four simanim, etc., in fetus found in treifah womb also treifah and has no remedy at all. And to reconcile—but according to most poskim who hold they do not depend on each other—it is fine to be difficult, and clear proof for Peri Chadash's words—and examine.`,
  '3#_': `Most with minority of limb—Shach explained: with this minority there is most of it outside; and they said we follow the majority—meaning now with the minority it is majority outside; and he strained unnecessarily, for the plain meaning is there is majority outside aside from this small amount, only inside half and outside half and a bit; and if we throw minority of hand outside inside—for majority of hand outside, behold inside is majority six and a quarter; but now aside from hand there is majority outside, we do not rule on minority of hand inside—and behold outside is majority; and it is plain; and this is the unresolved question that was resolved; and we judge in it both leniently and stringently.`,
  '4#_': `And if it cut—this too is unresolved and there is practical difference between doubt and certainty; and one cut, etc., until only minority remained in the animal, and that minority majority of limb outside—there is to permit from force of double doubt that birth did not apply to minority of limb remaining inside, if we say there was birth for we follow majority, perhaps majority was not born—for majority is in one eye and this is cut and stands. And if so, permitted; and from this reason they wondered on Rif and Rambam who omitted this unresolved question "limb came out and was cut"—though ostensibly unstam like the explanation that even though they did not cite, nevertheless we judge stringently, and from such reasoning leniently seems reasonable, and if they cited also stringently there is no practical difference—and according to what I wrote it is fine. And behold I have a doubt regarding its head that came out cut—whether it is yelud or perhaps specifically its majority as we say "its majority" in one case we require, unlike head. And behold our great rabbi Maharsha at beginning of chapter Behemah HaMekishah that Tosafot wrote on complete offspring whether yelud even if inside was yelud, and in cutting it is the unresolved question below, etc., and Maharsha wrote: in this whole one that came out partially where there is only pressing and nevertheless what is inside is yelud—it must be preferable to cutting—end of his words; and from this it is proved he holds even for head the unresolved question of the Gemara applies, otherwise Maharsha would not challenge anything—and see there he was precise from Tosafot's words. However from Rashi it appears the opposite—Rashi in Bava Kamma daf 11: afterbirth that part came out is forbidden—explained we are concerned perhaps in that part there was majority of offspring; and so Rosh and Rashba in chiddushim to Bava Kamma: perhaps in that part was its head or its majority. And Maharam of Lublin challenged: if so what does the Gemara challenge in Chullin our mishnah "its head too we taught siman and offspring, etc."—what difficulty, there the reason is because of its majority; and he left it requiring study. And in chiddushim I wrote many things. But in plainness of the sugya it must be that there it deals with R' Eliezer and there is an establishment in the Gemara in Niddah chapter HaMapelet that R' Eliezer holds like Shmuel that head does not exempt in miscarriages; and the reason must be because of its majority; and if so Maharsha's challenge in its place—what will its majority help, behold it was dissolved like cutting. But this is not so—for truly for R' Eliezer who holds head does not exempt, etc., the unresolved question applies even in cutting it is yelud. But the unresolved question in Chullin goes to conclusion that we hold head exempts in miscarriages; and if so one may say that of afterbirth that part came out is because of departure of its head, but not because of its majority; and for head there is no practical difference in cutting and in majority we are doubtful; and if so the Gemara's challenge at beginning of their chapter also on this revolves—cutting does not nullify majority of that afterbirth that is not because of its head—what does the mishnah teach us, we taught afterbirth, etc.; and the Gemara's words are correct and clear, and not like Maharsha. However in this I thought to resolve the reason Rambam omitted this unresolved question "cut it, etc."—why is it difficult for Rambam that Tosafot's challenges why does the Gemara challenge at beginning of Behemah HaMekishah "its head we taught afterbirth, etc."—perhaps there because we decree part of it because of all of it. And Shmuel's answer who holds head does not exempt in miscarriages—that afterbirth part came out—how establish it, and to say we are concerned its majority came out—Rambam does not hold like this, as appears Tosafot too do not hold, and the reason because "part came out" we taught even a slight thing where there is no doubt in majority of offspring (and in chiddushim I answered Maharam's challenge on Rashi that it must be part of a slight thing, for otherwise what does it teach us that afterbirth is forbidden—behold that pressing that came out is certainly forbidden and mixed with pressing inside and plainly forbidden)—end of his words—that something very slight came out until mixture is nullified in majority; but according to those who say if it returned the limb it is permitted, one may say it deals with that afterbirth that part came out, it returned it, and there is no concern of mixture, only therefore forbidden lest there be concern for birth. And if so in Bava Kamma for R' Eliezer who holds head does not exempt—we must be concerned for departure of majority; and if so only a little came out, for otherwise anyway forbidden because of mixture; one may say R' Eliezer holds if it returned it is permitted, but at beginning of HaMekishah the challenge is for Rav who holds the limb itself is forbidden—if so not needed thus, and one must say something slight came out and only concern for head—and examine. To resolve this, Rambam holds at end of chapter HaMekishah amoraim disputed this afterbirth that came out, etc.—some say specifically there is no offspring with it but there is—we are not concerned for offspring; and some say, etc.; and it is taught like my view—even if there is, nevertheless forbidden; and Rambam holds: granted if there is no offspring with it, which is certain offspring, fine to say part because of all, for all that came out is certain prohibition; unlike if there is offspring with it, which is only doubt how to decree part because of all—for all that came out its body is only doubt of offspring, and we do not decree so much; and if so fine Shmuel who holds head does not exempt holds in the mishnah the reason is part because of all; and he truly holds as those who say it deals where there is no other offspring with it; but sugya of HaMekishah comes to conclusion as taught that there is other offspring with it; and if so not needed part, etc., as I wrote—and therefore the reason we are concerned its head came out, and fine it challenges—and examine. If so Rambam's words are also correct that he holds the unresolved question in Gemara regarding cutting was resolved; and the challenge from Maharsha from afterbirth part came out does not challenge him—for in afterbirth we decree part because of all that certainly like yelud even if completely dissolved. And this is all according to those who hold there is no other offspring with the afterbirth; but according to what we hold as taught that even if there is offspring nevertheless forbidden—if so not needed part because of all; and if so the reason it is forbidden is we are concerned its head came out; and learn from this that even in cutting it is yelud; and this unresolved question was resolved; and therefore Rambam omitted—and examine. And it is clarified for us from this conclusion that also in Rosh this unresolved question applies like Maharsha, and certainly resolved stringently; and in any case there is no substance in the words of the author of Pri Toar that his view is to be lenient plainly if the whole offspring was cut into limbs and all limbs inside were not forbidden—and this is error, for aside from afterbirth that came out, etc., it is difficult for him as above, also this mishnah "came out cut, etc."—and though Tosafot wrote to distinguish what remained inside only to clarify the doubt of the author of the unresolved question, but heaven forbid to decide to be lenient; and his words are void words to permit prohibition—heaven forbid—and examine.`,
  '5#_': `And behold this is like milk, etc.; and the Bach and Shach agreed that if there appear sixty in the animal against this limb, permitted; and though Perishah and Taz argue who can estimate how much milk comes from each limb—the Shach wrote certainly majority exists and min b'mino from Torah nullified in majority, and it is like nispach below in mixtures and permitted; and so Peri Chadash; and they did not need this only that it is double doubt, one lest there are sixty in limbs, and if we say there are not sixty, why is the law that milk is not forbidden at all—for this is the unresolved question that was not resolved; and according to rules of double doubt it enters among doubts according to many authors. And behold the rabbi author of Mishneh Lamelech in Laws of Tumat Tzaraat argued: if so it is rabbinic doubt—certainly in majority it is nullified; if so why did it rule teiku stringently that forbids and did not rule leniently that milk does not forbid; and therefore he proved the essence is like Mordechai in chapter Zeroa Beshela, etc., who holds where permission is immediately mixed with prohibition like yevamah who spat blood that is immediately mixed with saliva droplets and the like—nullification does not apply; and this too is similar, for immediately when milk prohibition and permission are mixed, nullification does not apply here. And he also brought in name of the comprehensive rabbi R' Chaim Alexandri that his view is the milk stands first separately in each and every limb, and there the milk is squeezed and afterward all descend into the udder—see there; and Mishneh Lamelech argued: if so the difficulty returns to its place—why did Rambam doubt this unresolved question stringently—see there. And behold what he argues that Rambam should have ruled leniently in rabbinic doubt is not a decisive matter to reject him—requires study; see Avnei Nezer siman 337 who brought in name of Hagahot Maimoniyot that a matter that arose in the Talmud as teiku—even for rabbinic prohibition we go stringently; and so later authorities in many places; and here it is teiku and stringently; and also since the prohibition substance is Torah-level only through mixtures it became rabbinic doubt—we do not say in it rabbinic doubt we do not say rabbinic doubt leniently as rabbinic doubt—see below general rules of double doubt in Shach s.k. 19 who wrote so in name of Darkei Moshe. (And possibly Mishneh Lamelech holds if prohibition stands separately and then it is Torah doubt to be stringent only after it mixed, its doubt does not go; but here it is not in reality that it will be separately, and if so immediately it is rabbinic prohibition—this forced distinction on Rambam is strained.) And if so the author of Mishneh Lamelech labored in vain. And truly the words of the rabbi R' Chaim may need us to say nevertheless that not from all limbs they come together into the udder and there milk is made—if so it is zeh v'zeh gorem kosher limb and treifah limb—and see Tosafot s.v. here "three," etc.; and see chiddushim of Maharam Lublin. But according to that rabbi, behold the milk stood separately in the forbidden limb and afterward descended into the udder and was absorbed in the other limb—they called it chalav; behold prohibition and permission mixed—and what relevance does zeh v'zeh gorem have; and this is what Rambam was precise in his clear language "and this is like flesh of treifah mixed, etc."—lest you say zeh v'zeh gorem and permitted; and he says not only mixture of complete milk. And in his words there is further side to permit: when treifah milk descends from forbidden limb into udder and in it milk from other limbs one by one nullified, and in min b'mino we do not say it revives. And behold I have difficulty in the Gemara that challenges and asks what is sucking its milk—even though there is prohibition of limb from the live animal—if you do not say the Merciful One permitted, see there. And it does not say all milk in general comes from milk and blood and the Merciful One permitted—and the same for this prohibition of limb from live animal—and why generally two and here three—for the Gemara's concern there is no milk prohibition in ben pakuah like R' Yehudah that its milk is permitted. And it is a great difficulty for me, for I did not find the commentators sensed it. And I would have said that certainly the whole question of the Gemara is on its milk, certainly nullified in the animal min b'mino in majority nullified, and the other is nispach as Shach wrote, and as I wrote perhaps one by one nullified—only this is when milk already came out and without doubt was nullified; but how was it permitted l'chatchila to leave the forbidden limb from which prohibited milk came out and it be nullified in permitted milk—is this not nullifying prohibition l'chatchila; and what difference between leaving forbidden piece for pot that its emission be nullified, and this case—certainly if impossible to cut the limb from the animal to discard it, plainly permitted for it was nullified and what should he do, and it is like prohibition that fell into permitted pot; but if in his hand to cut the limb and not leave it that milk flow from it—also plainly forbidden, for it is nullifying prohibition; and on this revolves the unresolved question in the Gemara "what is sucking its milk"—if forbidden, forbidden to leave the limb that its milk flow and be nullified, for it is nullifying prohibition; or leave the milk to forbid it; or cut the limb—and we conclude as doubt stringently; and this is what Rambam wrote "and the milk is forbidden to drink, since it comes from all limbs in which there is prohibition; and this is like milk of treifah, etc."—if so if he drinks he nullifies prohibition by hand—for if permitted to leave to nullify piece to which milk adheres without cutting it that it mix in pot—is this not nullifying prohibition; and what difference whether he leaves limb—behold nullifying prohibition; and forbidden to drink the milk even if nullified—and clear. But this if possible to cut and remove; but if impossible, plainly not nullifying prohibition and permitted; therefore the Gemara did not bring from milk and blood—for this is not in category of nullifying prohibition, and when he removes from animal its milk and blood, and if so plainly permitted for afterward nullified in majority, and they did not decree further; but from this limb it is fine to ask—for behold in his hand to cut it, and it is nullifying prohibition like milk adhering to piece. And behold in the Gemara in Bekhorot daf 72 they debate: from where do we know pure milk is permitted—and the Gemara says the reason that it nurses from live limb. And there is to forbid it; and the Gemara brought verses from "price of wine and milk," "ten milk pans," etc.; and it is difficult why it did not say the reason that it nurses from milk as we say here to forbid nursing from outgoing limb. And in this there is no proof from those verses it brought—for perhaps regarding milk from chayah where there is no milk prohibition; and why did the Gemara choose nursing from live limb—certainly the Gemara knew it is nullified in majority, and therefore asked on limb from live animal that is entirely prohibition and there is no nullification at all; and later words somewhat compelled—and examine.`,
  '6#_': `In its mother's womb it is not called shechitah—or this law that implies even b'dieved treifah requires study, for the later authorities Taz, Shach, and Peri Chadash gave the reason it is unresolved and challenged Pri Megadim who gave reason of chaladah. Truly in Gemara Chullin daf 74b R' Eliezer asked: one extended his hand into animal's womb and slaughtered nine-month alive, etc.—what is the law; and R' Chanina resolved from mishnah: behold one born treifah from the womb—for it has no time of fitness; and if so, behold it has time of fitness—for if he wishes he puts in his hand and slaughters; Rava said to him: teach "formed treifah from the womb"—end. And Rashba cited in chiddushim and so Ran, and they wrote: since it was not resolved, we go stringently; but Rif, Rambam, Rosh, Tur, and Rashba in Torat HaBayit omitted it. And from this it implies they were not concerned. But go learn Tosafot's words in Beitzah daf 6 s.v. "and if what, etc."—they challenged why the Gemara says calf born from treifah—for it has no twilight on Yom Tov time of fitness, it is not prepared through its mother who is treifah; and Tosafot wrote: and it is astonishing—behold it is prepared, for we say in Chullin ben pakuah is permitted through four simanim through mother's shechitah or through its own; and if so he can extend his hand into its mother's womb and slaughter it and it will be prepared. And one may say the Gemara speaks according to Rav Oshaya who established there in Chullin whether ben pakuah is permitted through four simanim; or one may say since l'chatchila one should not slaughter in this manner, since he cannot see anything—as slaughtering at night that is forbidden l'chatchila—it is not called prepared—end. Here Tosafot's words need explanation—for what does it call to him, is it not plain it is unresolved and from such reasoning to challenge, and why Tosafot's challenge and resolve unresolved question there from this here—this matter in Beitzah is not a baraita, only question of R' Kahana and R' Eliezer to Rav, and whence resolve. And Tosafot's answer that it speaks according to R' Eliezer—for we do not find anyone disputes Rav Oshaya, and he is unresolved. And the essence answer: it is like slaughtering at night—what did they want with this, for from law it is forbidden even b'dieved—and see Piskei Tosafot Beitzah siman 22 who wrote one does not slaughter at night l'chatchila—end; behold he ruled for practical law b'dieved permitted, and it is against the Gemara above; and all Tosafot commentators did not address this. And what appears—that Tosafot and the other poskim who omitted this unresolved question hold that what Rava said "teach formed treifah from womb"—Rava did not intend to emend the mishnah from his heart, only such was the tradition in his hand that the mishnah must say "formed from womb"; and if so one may infer the opposite—why did the mishnah teach "formed from womb," which is uncommon, and not teach the common "born from womb"; nevertheless they had time of fitness—learn from mishnah that it holds one can extend hand into animal's womb and slaughter; and therefore it had to teach "formed from womb," for there is no time of fitness; and if so from Rava's words the unresolved question was resolved and therefore those poskim omitted. And this is Tosafot's view, and therefore they challenged there in Beitzah that it has time of fitness to slaughter in womb if like conclusion of the matter; and therefore answer in one resolution that they speak according to Rav Oshaya—for he does not have Rava's version in mishnah and it is doubtful to him and comes according to him; or that it comes according to conclusion like Rava, and nevertheless forbidden l'chatchila, for it is like slaughtered at night. And on this Piskei Tosafot hold that for practical law like Rava the unresolved question was resolved, only forbidden initially as slaughtering at night. And if so this law of Rama and later authorities is in great dispute—we say, and many poskim permit, until Rashba himself though in chiddushim he brought it in Torat HaBayit he omitted, and possibly Pri Megadim too holds the unresolved question was resolved like Tosafot, and holds Tosafot's reasoning that the reason of prohibition is similarity to chaladah, not that it is truly chaladah, as later authorities wrote it is not called chaladah only similar to chaladah and forbidden l'chatchila; and Tosafot's challenge in Beitzah is resolved that it is not called prepared since initially forbidden as above. And behold I found support for this in sugya of crushing limbs Chullin daf 61 that R' Nachman said: house of womb has no concern of crushing limbs; and the Gemara brought support from that which we taught: calf born on Yom Tov one slaughters it on Yom Tov; and it rejected exceptional birth and again brought support from that which we taught: and they are equal that if born with its blemish with it, this is from the prepared; certainly on spreading on ground. And all wondered why it did not answer immediately with first support on spreading on ground. And it appears what the Gemara answers on that baraita of exceptional birth is that otherwise it must be exceptional birth—for there on Beitzah page cited, Rav taught: calf born on Yom Tov is permitted for it is prepared through its mother in shechitah; chick born on Yom Tov is forbidden for not prepared through its mother; and the baraita is difficult: what R' Kahana and R' Eliezer asked Rav what difference between this and calf born from treifah—and if Rav was silent, how do we resolve; and see Shitah Mekubetzet what he wrote there. And one must say Tosafot's challenge to answer that one can extend hand into animal's womb to slaughter—and it is difficult, for l'chatchila forbidden like slaughtering at night for he does not see the shechitah. But if it deals with exceptional birth that otherwise anyway one does not slaughter on Yom Tov because of crushing limbs, and exceptional birth is that mother was cut and offspring removed—if so fine it is prepared like Tosafot's challenge to extend hand into animal's womb; and if slaughtering at night like cutting mother and womb place where born rests, then there is covering and eye sees how he slaughters and it is like slaughtering by day, and even l'chatchila permitted, and fine it is prepared—and examine. And this is clear as above, and so in Shitah Mekubetzet to Beitzah explained in name of Ritva also like Tosafot that forbidden to extend hand into its mother's womb to slaughter for it is like slaughtering at night—and examine.`,
});

// --- pitchei-teshuva (5) ---
patchFile('siman_014/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>What came out from the limb.</b> Here the law of issur yotzei is stated in the Talmud regarding ben pakuah that koshered it, that every offspring is permitted through mother's shechitah; therefore outgoing limb has no remedy, unlike when mother is treifah. Indeed Shach's view below s.k. 7 is clear that even when mother is found treifah issur yotzei applies and what is outside is forbidden. However Peri Chadash disagreed—see in Levushei Serad who wrote it appears the essence is like Peri Chadash, but for practical law one should be stringent and say if the limb that came out is a limb on which the soul depends, forbid all of it even what was inside, and when it grows its milk is also forbidden (and if there is another side of permission such as mixture, etc., one may permit—see in my explanations s.k. 7); and if it is a limb on which the soul does not depend, be concerned and forbid the outgoing limb in any case, and the rest is permitted through its own shechitah, and when it grows its milk is permitted—see there.`,
  '2#_': `<b>That came out and was returned is permitted.</b> See in responsum Beit Shmuel Acharon part 4 siman 9.`,
  '3#_': `<b>In kosher milk.</b> Avodat HaGershuni; and see in Sefer Bnei Chiya who disagrees with Shach and Peri Chadash who agreed to permit the milk if there are sixty in the animal against the forbidden limb—for they omitted Mordechai's words in Chullin daf 560 who wrote there is no nullification except in a thing that was recognizable by itself at first and afterward mixed, but in a thing whose entry into the world began mixed, it is not nullified—see there; also Mishneh Lamelech chapter 1 of Laws of Tum'at Metzora law 14 brought what Mordechai wrote that a thing mixed from the beginning of its creation has no nullification, and wondered on the Ashkenaz later sages who debated here whether milk is nullified in sixty—see there where he elaborated; and see in responsum Noda Biyehudah Tinyana part Yoreh Deah siman 54 that there is this difficulty, and he wrote Mordechai's words are only regarding nullification that we come from Torah law of majority, but in a thing nullified in sixty whose reason for nullification is because then the taste is not sensed—the Mordechai's distinction does not apply—see there.`,
  '4#_': `<b>And if he slaughtered a fetus in its mother's womb.</b> See in responsum Tiferet Tzvi part 4 siman 69 in middle of responsum who wrote its mother in any case is permitted even without checking internal organs, and we are not concerned perhaps he touched them with the knife—for one need not be concerned when he intends not to touch other limbs; and he proved so from Tosafot in Beitzah daf 6—see there.`,
  '5#_': `<b>It is not called shechitah.</b> See on this in responsum Shevut Yaakov part 1 siman 45.`,
});

// --- rabbi-akiva-eiger-yd (3) ---
patchFile('siman_014/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 14 seif 5) <b>Its milk is forbidden to drink.</b> And if half came out with majority of limb, one may say the milk is permitted because of double doubt: doubt whether it is yelud, and there is no issur yotzei here; and if we say it is not yelud, doubt that perhaps regarding what came out the milk is also permitted; and ostensibly this is hidden from what the Taz wrote s.k. 6 regarding ben pakuah that came on superior animal that the offspring has no remedy through shechitah—the milk is forbidden—for this too is among the unresolved questions—see there; and behold this law of ben pakuah on superior animal that offspring has no remedy because we are concerned for father's seed is only a doubt, as we hold in siman 15 that for practical law we hold it is doubtful whether we are concerned for father's seed; and if so it is double doubt. However one may say: there regarding doubt whether concerned for father's seed, the offspring has presumption of prohibition that it is not slaughtered, and we judge from presumption that it has no remedy through shechitah; but here with half and majority of limb one may say we do not say it is certainly not yelud that shechitah does not help what came out—for regarding what remained inside the presumption of prohibition is reversed to judge it yelud, that if it were not yelud it would immediately be permitted through mother's shechitah; and from presumption of prohibition it is fit to judge it was not permitted; and if so there is presumption here and there; therefore one may say it is fine as double doubt.`,
  '2#_': `(Shach s.k. 12) <b>That it should only be a doubt whether there are sixty.</b> But if certainly there are not sixty, one may not permit it by law of rabbinic doubt because of doubt in the unresolved question whether milk is permitted—for since milk from force of outgoing limb is Torah doubt, as Taz and Shach wrote (siman 66 and siman 110); in Pri Megadim he wrote on this: even though Maharival wrote where there is Torah doubt and afterward it rolled that it is rabbinic—we do not say rabbinic doubt leniently—one must say since at beginning of its creation it was in mixture, fine it is rabbinic doubt. And Turei Zahav challenged: also when certainly there are not sixty to permit, it is rabbinic doubt from force of unresolved question—see there in Machatzit HaShekel that he erred in this, for what relevance does this have to Maharival's law, for there certainly there is no measure of rabbinic nullification, only it comes to say since from Torah nullified in majority it is rabbinic doubt lest it not be treifah—in this we say since doubt of treifah in its bones is Torah doubt, it requires nullification like certain Torah prohibition—this is called rolling of rabbinic; but here the doubt whether there are sixty that also rabbinically nullified—this is like nispach that we are lenient lest there were sixty, and it is very plain; and automatically the Turei Zahav's challenge is removed that if certainly there are not sixty, the doubt of unresolved question does not help—we judge it rabbinic doubt, which is truly like Maharival's law. Only Turei Zahav challenged thus from reasoning, since at beginning of its creation it was majority and there was no reality of Torah prohibition—it is fit to say rabbinic doubt leniently.`,
  '3#_': `(Seif 6 in hagahah) <b>It is not called shechitah.</b> I am doubtful: if the mother died and he slaughtered the offspring in its mother's womb—in this one may say it is shechitah, for it only asks when the mother is alive, for then one may say the offspring is like part of the mother and not behemah separately; but when mother died, one may say the offspring is only like placed in a box and considered born. And as Ramban brought in Magen Avraham (siman 339 s.k. 15) that though Yisrael is not executed for fetuses, nevertheless when mother died the fetus is yelud and a door is locked before it. However according to Levush's reason that it is chaladah, also in such a case it is not shechitah. And in essence of the law it is difficult for me why Rama needed to bring this law, for Rama already wrote above (siman 13 seif 3) that if mother was slaughtered and found treifah, now the offspring has no remedy, for we are not expert whether its months were completed; if so automatically one cannot permit slaughtering offspring in mother's womb without permission of mother's shechitah, lest its months were not completed and it has no own shechitah. And perhaps Rama's intent is it is not shechitah at all even to be lenient that it is permitted to slaughter the mother afterward—for it is not oto v'et beno; and this is because it is double doubt: doubt lest months not completed, and if we say they were completed, perhaps shechitah in mother's womb does not help—and requires study (and not like Shach wrote who is stringent regarding oto v'et beno).`,
});

// --- nekudot-hakesef (2) ---
patchFile('siman_014/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `<b>(Siman 14 s.k. 7) And in my humble opinion one should not be lenient, etc.</b> See in Siftei Kohen small seif 12 that one may be lenient because of doubt leniently. Also what he compared to eggs below siman 86 is not similar, as Shach wrote siman 81 s.k. 7—see there.`,
  '2#_': `<b>(s.k. 10) And it is an error, etc.</b> Lechem Chamudot already preceded on this, and as Shach wrote s.k. 14.`,
});

// --- kaf-hachayim (6) ---
patchFile('siman_014/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>(1) [Seif 1] The animal straining to give birth.</b> At time of shechitah. Rashi Chullin 68a. And he mentioned "straining"—see there that birth was with difficulty. Zivchei Torah siman 1.`,
  '2#_': `<b>(2) There. And the fetus brought out its head.</b> And one need not all the forehead, only until most of its forehead. Perishah siman 1; Taz s.k. 1; Shach s.k. 1; Peri Chadash siman 1 for practical law siman 1; Levushei Serad siman 1; Kereti siman 2; Zivchei Torah siman 2. And specifically stringently one may say so, but leniently it is not yelud even with departure of entire forehead until one estimates majority of its head came out. Shaarei Deah siman 2; Pri Deah siman 1; and practical difference: if nine months dead, all forbidden lest it be yelud; if alive, what is outside forbidden lest not yelud, and what is inside permitted through its own shechitah in any case. Pri Deah there. Zivchei Tzedek siman 1.`,
  '3#_': `<b>(3) There. Even though it returned it, behold it is yelud.</b> For we derive from adam "all in whom breath of life," etc. Zivchei Torah siman 3.`,
  '4#_': `<b>(4) There. If eight months alive or dead or nine months dead—forbidden.</b> And it is not permitted through mother's shechitah nor through its own when eight months even alive, for it cannot live. Levush.`,
  '5#_': `<b>(5) There. Forbidden.</b> Even though it returned the head and remained in mother's womb until its months completed before mother's shechitah, or was born entirely before mother's shechitah after its months completed. Shaarei Deah siman 1; Minchat Yitzchak siman 1.`,
  '6#_': `<b>(6) There. Forbidden—all of it.</b> Shach s.k. 2—for it is like neveilah. Zivchei Torah siman 4.`,
});

// --- yad-avraham (2) ---
patchFile('siman_014/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 14 seif 4) <b>And if it cut each limb when it brought it out—that too the minority inside is forbidden.</b> This is unresolved in the Talmud at beginning of HaMekishah: do we require its majority at once or not, and it ruled stringently that it is yelud. And it requires study—for what does it need to resolve for him from that which we taught there (daf 69) regarding firstborn: majority came out, behold yelud and exempt from firstborn. And it is proved there explicitly in Talmud, Rashi, Tosafot, Rambam, and Tur siman 319—that it applies whether majority came out at once or limb by limb—see there. And one must say there is nothing to resolve from firstborn—for regarding opening the womb the Merciful One depended, and behold the first womb opened with its majority and exempts what comes after. See Rashi there. But regarding fetus that depends on birth, perhaps nevertheless minority inside is not yelud. And similarly Tosafot wrote there (daf 68b) s.v. "brought out," etc., and at beginning (daf 70)—see there. <b>With this</b> the wonder of Tosafot at beginning of HaMekishah s.v. "the reason, etc." is resolved—why did the Talmud not resolve that departure of head is yelud from what it taught regarding firstborn. And according to what I wrote to reconcile, and therefore he inferred from firstborn to inheritance that it did not depend on opening womb alone but that it be viable offspring, and learn that all of it is yelud; otherwise behold the head alone is not fit to be viable offspring—and see there the sugya and you will understand what I wrote is clear.`,
  '2#_': `(Seif 6 in hagahah) <b>And if he slaughtered a fetus in animal's womb, it is not called shechitah.</b> Unresolved in chapter HaMekishah and was not resolved. And I did not reach the end of the hagahah's view that followed the Talmud in this—for it is explicit in Talmud and Rashi (daf 74) and Tosafot (daf 75 end of seif 1) and Rashba and Ran that it is only a question regarding nine months alive, but eight months alive there is no question at all. And so Tosafot in first chapter of Beitzah (daf 6 seif 1)—for even if it went out into air of the world shechitah does not apply, for it is like dead; behold like cutting in slaughtered flesh as in Shabbat (daf 136)—see there. And if so the hagahah should not have written this law—for even if it went out into air of the world and he slaughtered it immediately, forbidden lest it is not nine months, as hagahah wrote above siman 13 seif 3—see there. However this is only from stringency side and it is not considered a doubt as written nearby; but this law is full doubt and practical difference for double doubt whether there are two doubts here: perhaps in mother's womb this is not shechitah at all, and if we say it is shechitah, nevertheless perhaps it is not nine months. However since we rule regarding wife of kohen that presumption of fitness applies, we follow majority of offspring. <b>Also</b> Shach's words who wrote forbidden to slaughter mother after it same day lest it be shechitah do not seem right—for certainly for need it is permitted to slaughter mother immediately after because of aforementioned double doubt; and after slaughtering eight-month alive certainly permitted to slaughter mother after it same day—for we hold eight months has no shechitah in its species and is not included in "and you shall slaughter from your cattle and flock," as explained in Talmud Rashi chapter HaMekishah (daf 72), and so Rambam chapter 2 of Laws of Fathers of Impurity, and Rashba in Torat HaBayit; and so Tosafot beginning chapter 3 s.v. "in offspring," etc., and Tosafot (end daf 100) that eight months is not called ox and sheep—see there. And if so it is not in "ox or sheep, it and its son you shall not slaughter," etc.—for here there is neither ox nor sheep nor shechitah, only like dead whose shechitah does not purify even from neveilah, as in Talmud there and Rambam as mentioned—see there. And such double doubt helps even in a thing that has permission tomorrow, as Shach wrote siman 110 s.k. 55; and see there seif 8 in hagahah.`,
});

// --- yad-ephraim (1) ---
patchFile('siman_014/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>And there is one forbidden limb.</b> Avodat HaGershuni; and Netiv Chaim wrote in Mishneh Torah siman 54 according to Mishneh Lamelech what Mordechai wrote end of Chullin in name of Rabbenu Meshullam that a thing mixed from beginning of its creation is not nullified; and from this he wondered on what later authorities wrote in siman 14 that regarding outgoing limb milk is nullified in sixty—for this is mixed from beginning of its creation; and he wrote that therefore nullification does not help, for otherwise why did they rule the unresolved question stringently regarding majority—for certainly there is majority here, and it should be rabbinic doubt leniently like mixture of min b'mino and nispach; and he answered: they too hold in majority it does not help from beginning of creation, only regarding sixty where the matter depends on taste, and where it is known there are sixty it is permitted since there is no prohibition taste here, unlike where there is doubt whether there are sixty—it is Torah doubt; and if so it is not similar to nispach that from Torah is nullified in majority, unlike here that is not nullified in mixtures from beginning of creation; and nevertheless on Shach it is astonishing who wrote nullified in majority, etc.—see there, and he was astonished. And nevertheless I wonder—in my humble opinion Mishneh Lamelech wrote well that even sixty does not help: granted if we come to forbid because of taste we judge sixty to nullify taste, unlike here where we do not come on taste—for from min b'mino it is only because nullification does not help in a thing from beginning of its creation, and it is as if the substance of prohibition here without nullification—what does sixty help for substance of prohibition, and it is similar to min b'mino according to those who say not nullified even in a thousand—not nullified; and that sixty helps in min b'mino is because its substance without taste is nullified in majority and prohibition is only because of taste, and since there are sixty there is no taste, as explained in Rashba Chullin daf 98; but where there is no law of nullification at all, one may not permit even if there are sixty, whether min b'mino or min she'eino mino; and even though taste is not sensed, since it stands in substance without nullification, and like swallowing prohibition—even though there is no sensed taste here it is forbidden; and this too in min she'eino mino where mixture in sixty helped to remove prohibition taste, and all the more in min b'mino where its taste was not removed at all—and there is no nullification here; and what will sixty help him. And that which we say in Chullin daf 98 to derive from "arm when cooked" regarding sixty—even though there it is min b'mino—Tosafot already wrote there that certainly there it was nullified in majority, they only relied on the verse; end of his words. But the essence law of sixty has place only in min she'eino mino where the substance has law of nullification—sixty helps to nullify taste; but where there is no law of nullification at all, even sixty does not help—and requires study.`,
});

